*Merge Lo Pucki dataset with the hand collection dataset;
proc sql;
	create table LP2 as
	select distinct a.*, b.*
	from LP1 as a left join HC1 as b
	on a.CaseNum = b. CaseNum AND a.Datefiled = b.DateFiled;
quit; 

*Retain observations filed after 2001;
data LP2; set LP2;

*Retain only chapter 11 cases;
data LP3; set LP2;
	if chapter = "11";
run;

*Drop firms whose cases were converted to chapter 7;
data LP4; set LP3;

*Retain private companies;
data NGR1; set NGR;
	if Public = "No";
	drop Security_1 -- Security_6_Ownership;
run;

*Create public indicator variable and set it equal to 0;
data NGR1; set NGR1;
	public2 = 0;
run;

*Format date variables;
data NGR1; set NGR1;
	Datefiled=input(substr(Bankruptcy_Date,1,10),yymmdd10.);	
	format datefiled MMDDYY10.;
	Date_filed_year = year(datefiled);

	DateEffective=input(substr(Effective_Date,1,10),yymmdd10.);
  	format DateEffective MMDDYY10.;

	DateConfirmed=input(substr(Confirmation_Date,1,10),yymmdd10.);
  	format DateConfirmed MMDDYY10.;
	Dateconfirmed_year = year(dateconfirmed);
run;

*Merge the hand collection spreadsheet to the main dataset;
proc sql;
	create table NGR2 as
	select distinct a.*, b.*
	from NGR1 as a left join HC1 as b
	on a.Case__ = b. CaseNum AND a.Datefiled = b.DateFiled;
quit; 

*Retain cases with more than $100M in prepetition assets;

		from B1 as a left join compd.funda as b
		on a.cik2 = b.cik and b.cik ~= "";
quit;

*Retain the last Compustat observation prior to the bankruptcy filing;
proc sort data=B1; by cik2 descending datadate conm datefiled; run;
proc sort data=B1 out=B2 nodupkey; by cik2 conm datefiled; run;

		from B2 as a left join compd.funda as b
		on b. gvkey ne ' ' and b. datadate ne . and b. indfmt='INDL' and b. datafmt='STD' and b. popsrc='D' and b. consol='C'
		and year(b. datadate)>= 1995 and b. datadate <= a. datefiled and a.gvkey = b.gvkey;
