*Retain the last Compustat observation prior to the bankruptcy filing;
proc sort data=C1; by gvkey descending datadate descending at_pre; run;
proc sort data=C1 out=C2 nodupkey; by gvkey cik2 conm datefiled; run;

*Obtain Compustat annual data from the first 10K filing after the bankruptcy announcement;
proc sql;
	create table C3 as 
		select distinct a.*, b. at as at_posta, b. sale as sale_posta, b. dm as dm_posta, b. dlc as dlc_posta, b. dltt as dltt_posta,
			b. che as che_posta, b. ib as ib_posta, b. pi as pi_posta, b. ppent as ppent_posta, b. invt as invt_posta, 
			b. datadate as datadate_posta, b. ebitda as ebitda_posta, b. dm as dm_posta, b. dlc as dlc_posta, b. dltt as dltt_posta
		from C2 as a left join compd.funda as b
		on b. gvkey ne ' ' and b. datadate ne . and b. indfmt='INDL' and b. datafmt='STD' and b. popsrc='D' and b. consol='C'
		and b. datadate >= a. dateconfirmed and a.gvkey = b. gvkey;
quit;

*Retain the first Compustat observation following the emergence from bankruptcy;
proc sort data=C3; by gvkey datadate_posta descending at_posta; run;
proc sort data=C3 out=C4a nodupkey; by gvkey cik2 conm datefiled; run;

*Obtain Compustat quarterly data from the first 10K filing after the bankruptcy announcement;
proc sql;
	create table C4b as 
		select distinct a.*, b. atq as at_post, b. dlcq as dlc_post, b. dlttq as dltt_post,
			b. rdq as datadate_post, b. prccq as prccq_post, b. piq as piq_post, b. udmbq as dm_post, b. cheq as che_post,
			b. cshoq as csho_post
		from C4a as a left join compd.fundq as b

		on b. gvkey ne ' ' and b. rdq ne . and b. indfmt='INDL' and b. datafmt='STD' and b. popsrc='D' and b. consol='C'
		and b. rdq >= a. dateconfirmed and a. gvkey = b. gvkey;
quit;

*Retain the first Compustat observation following the emergence from bankruptcy;
proc sort data=C4b; by gvkey datadate_post descending at_post; run;
proc sort data=C4b out=C4 nodupkey; by gvkey cik2 conm datefiled; run;

/*Obtain CRSP Data - Start by obtaining the historical cusip;*/
proc sql; 
	create table C4 as

	select distinct a.*, b. lpermno, b. linkprim, b. linktype as linktype2  
	from C4 as a left join crsp.ccmxpf_linktable as b 
	on a.gvkey = b.gvkey and b.lpermno ne . and
        (b.LINKDT <= a.datadate_post or b.LINKDT = .B) and (a.datadate_post <= b.LINKENDDT or b.LINKENDDT = .E); 
quit;

*Fix duplicate links - gives priority to the more high quality links;
data C4; set C4; 
	if  LINKPRIM='P' THEN LINKTYPE=1; 
	if  LINKPRIM='C' THEN LINKTYPE=2; 
	if  LINKPRIM='N' THEN LINKTYPE=3; 
	if  LINKPRIM='J' THEN LINKTYPE=4; 
run; 

proc sort data=C4; by gvkey datefiled Case_Num LINKTYPE; run; 
data C5; set C4; by gvkey datefiled Case_Num LINKTYPE; if first.gvkey = 0 and first.datefiled = 0 and first.Case_Num = 0 then delete; run; 
data C5; set C5; drop  LINKPRIM LINKTYPE; run;  

*Link to HISTORICAL 8 digit cusip; 
proc sql;
	create table C6 as 
	select distinct a.*, b.ncusip, b.ticker as tickercrsp, b.shrcd
	from C5 as a left join crsp1.stocknames as b 
	on a.lpermno=b.permno and b.ncusip ne ' ' and b.ncusip ne '00000000' and b.namedt<=a.datadate_post<=b.nameenddt; 
quit;

*If historical cusip is missing, use the current cusip;

data C5; set C4; by gvkey datefiled Case_Num LINKTYPE; if first.gvkey = 0 and first.datefiled = 0 and first.Case_Num = 0 then delete; run; 
data C5; set C5; drop  LINKPRIM LINKTYPE; run;  

*Link to HISTORICAL 8 digit cusip; 
proc sql;
	create table C6 as 
	select distinct a.*, b.ncusip, b.ticker as tickercrsp, b.shrcd
	from C5 as a left join crsp1.stocknames as b 
	on a.lpermno=b.permno and b.ncusip ne ' ' and b.ncusip ne '00000000' and b.namedt<=a.datadate_post<=b.nameenddt; 
quit;

*If historical cusip is missing, use the current cusip;
data C6; set C6;
	if ncusip = '' then ncusip = cusip;

data ibes_guidance_detail; set ibes.id_guidance; run;
data ibes_guidance_id; set ibes.det_guidance; run;

proc sort data=C6; by gvkey datefiled; run;

*Merge in firm identifier information (obtained from IBES Guidance);
