proc sort data=C6; by gvkey datefiled descending anndats; run; 
proc sort data=C6 out=C6 nodupkey; by gvkey cik2 conm datefiled; run; 

*Merge in IBES analyst coverage;
proc sql; 
	create table analyst as select distinct a.gvkey, a. datefiled, a. dateconfirmed, a.datadate, a.cusip, b.statpers, b.numest 
	from C6 as a , ibes.STATSUMU_EPSUS as b 
	where a.ncusip=b.cusip
	and b.numest ne .
	and b.measure='EPS' 
	and b.curcode='USD'
	and b.fpi='1'
	and (a. datefiled - 1825) <= b. statpers <= (a. datefiled + 1825);
quit;

