	select distinct a.*, b.file_date as file_date_302, b.PERIOD_END_DATE_NUM as PERIOD_END_DATE_302, b.IS_EFFECTIVE, b.MATERIAL_WEAKNESS
	from NR as a left join aa302 as b 
