data DA; set DA;
	gvkey2 = put(gvkey, 10.);
	gvkey2 = compress(gvkey2);

	if length(gvkey2) = 2 then gvkey2 = cats('000',gvkey2);
    else if length(gvkey2) = 4 then gvkey2 = cats('00',gvkey2);
    else if length(gvkey2) = 5 then gvkey2 = cats('0',gvkey2);
    else if length(gvkey2) = 6 then gvkey2 = gvkey2;
run;

